/*
 * Reading data/parliament-current.json (generated by `npm run parliament`): who holds which federal
 * function, and seats grouped by the site's parties. Pure functions, without DOM or data import,
 * shared by the site and by `npm run check` (tools/cli.ts).
 */
import { PARLIAMENT_FUNCTIONS, type Parliament, type ParliamentPerson } from "../types.ts";

export type Council = "CN" | "CE";

const FEDERAL_COUNCIL_FUNCTIONS: readonly string[] = [
  PARLIAMENT_FUNCTIONS.president,
  PARLIAMENT_FUNCTIONS.vicePresident,
  PARLIAMENT_FUNCTIONS.federalCouncillor,
];

export function holds(p: ParliamentPerson, fn: string): boolean {
  return p.activeFederalCouncilMandates.some((m) => m.function.key === fn);
}
export function isFederalCouncillor(p: ParliamentPerson): boolean {
  return FEDERAL_COUNCIL_FUNCTIONS.some((fn) => holds(p, fn));
}
/** The mandates a Federal Council member holds as head of a department (not as deputy). */
export function ownMandates(p: ParliamentPerson): ParliamentPerson["activeFederalCouncilMandates"] {
  return p.activeFederalCouncilMandates.filter((m) => FEDERAL_COUNCIL_FUNCTIONS.includes(m.function.key));
}
export function membersOf(parliament: Parliament, council: Council): ParliamentPerson[] {
  return parliament.persons.filter((p) => p.council?.abbreviation === council);
}

/** The API's party label of a person; "-" when the API records none. */
export function partyLabel(p: ParliamentPerson): string {
  return p.party?.shortName ?? "-";
}

/** Seats of one party of the site, or of the parties folded into "Autres". */
export interface SeatGroup {
  /** `abbr` of a CH party in parties.json; null for "Autres". */
  abbr: string | null;
  seats: number;
  /** Seats by API label, the largest first ("PLR" 26, "PLD" 1). */
  labels: [string, number][];
}

/**
 * Seats by party of the site, in the order of `order` (the CH parties from left to right), then
 * "Autres" for every label without a party in `order`. A party with no seat is left out.
 */
export function seatGroups(parliament: Parliament, persons: ParliamentPerson[], order: readonly string[]): SeatGroup[] {
  const byGroup = new Map<string | null, Map<string, number>>();
  for (const p of persons) {
    const label = partyLabel(p);
    const mapped = parliament.party_mapping[label];
    const key = mapped !== undefined && order.includes(mapped) ? mapped : null;
    const labels = byGroup.get(key) ?? new Map<string, number>();
    labels.set(label, (labels.get(label) ?? 0) + 1);
    byGroup.set(key, labels);
  }
  const groups: SeatGroup[] = [];
  for (const key of [...order, null]) {
    const labels = byGroup.get(key);
    if (!labels) continue;
    const sorted = [...labels].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    groups.push({ abbr: key, seats: sorted.reduce((n, [, v]) => n + v, 0), labels: sorted });
  }
  return groups;
}

/** Persons mapped to the site party `abbr` (PLD and Al included with the PLR and the Greens). */
export function partyMembers(parliament: Parliament, persons: ParliamentPerson[], abbr: string): ParliamentPerson[] {
  return persons.filter((p) => parliament.party_mapping[partyLabel(p)] === abbr);
}
/** The API label most persons of the site party `abbr` carry ("PLR"); null when the party has nobody. The others are regional labels ("PLD"). */
export function mainLabel(parliament: Parliament, abbr: string): string | null {
  const counts = new Map<string, number>();
  for (const p of partyMembers(parliament, parliament.persons, abbr)) counts.set(partyLabel(p), (counts.get(partyLabel(p)) ?? 0) + 1);
  let best: string | null = null;
  for (const [label, n] of counts) if (best === null || n > (counts.get(best) as number)) best = label;
  return best;
}
